from collections import defaultdict, deque

def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        edges = []
        for _ in range(m):
            t_i, x_i, y_i = map(int, input().split())
            edges.append((t_i, x_i - 1, y_i - 1))

        # Check for initial directed cycles
        graph = defaultdict(list)
        in_degree = [0] * n
        for t_i, x_i, y_i in edges:
            if t_i == 0:
                graph[x_i].append(y_i)
                in_degree[y_i] += 1

        # Topological sort using Kahn's algorithm
        queue = deque([i for i in range(n) if in_degree[i] == 0])
        visited = set(queue)

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor in visited:
                    print("NO")
                    break
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
                    visited.add(neighbor)
            else:
                continue
            break
        else:
            print("YES")
            for t_i, x_i, y_i in edges:
                if t_i == 0:
                    if x_i in graph and y_i in graph[x_i]:
                        print(x_i + 1, y_i + 1)
                    else:
                        print(y_i + 1, x_i + 1)
                else:
                    print(x_i + 1, y_i + 1)
